def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def act1(n): return ' Sólo puedes activar 1 "%s" por turno.' % n
CH = '"Charmer"'
FP = '"Familiar-Possessed"'
SC1500 = 'monstruo de Tipo Lanzador de Conjuros con 1500 de DEF'
def charmer(attr): return 'VOLTEO: selecciona 1 monstruo de %s que controle tu adversario; toma el control de él mientras esta carta esté boca arriba en el Campo.' % attr
def fam(n, attr, extra=''):
    return ('Puedes Invocar esta carta de Modo Especial (desde tu mano o Deck) mandando al Cementerio 1 "%s" boca arriba y 1 monstruo de %s boca arriba de tu Zona de Monstruos. ' % (n, attr)) + extra + 'Si esta carta Invocada de Modo Especial por su propio efecto ataca a un monstruo en Posición de Defensa, inflige daño de batalla de penetración.'
def chan(n, attr, mid):
    return '(Esta carta se trata siempre como una carta ' + CH + '.)\n' + mid + (' Cuando tu monstruo de %s sea destruido en batalla: puedes Invocar esta carta de Modo Especial desde tu mano.' % attr) + each(n)
ES = {
"Hiita the Fire Charmer": charmer('FUEGO'),
"Dharc the Dark Charmer": charmer('OSCURIDAD'),
"Wynn the Wind Charmer": charmer('VIENTO'),
"Aussa the Earth Charmer": charmer('TIERRA'),
"Lyna the Light Charmer": charmer('LUZ'),
"Eria the Water Charmer": charmer('AGUA'),
"Familiar-Possessed - Hiita": fam("Hiita the Fire Charmer", 'FUEGO'),
"Familiar-Possessed - Dharc": fam("Dharc the Dark Charmer", 'OSCURIDAD', 'Cuando sea Invocada de esta forma: puedes añadir a tu mano 1 monstruo de Tipo Lanzador de Conjuros de LUZ de Nivel 3 o 4 de tu Deck. '),
"Familiar-Possessed - Wynn": fam("Wynn the Wind Charmer", 'VIENTO'),
"Familiar-Possessed - Aussa": fam("Aussa the Earth Charmer", 'TIERRA'),
"Familiar-Possessed - Lyna": fam("Lyna the Light Charmer", 'LUZ', 'Cuando sea Invocada de esta forma: puedes añadir a tu mano 1 ' + SC1500 + ' de tu Deck, excepto "Familiar-Possessed - Lyna". '),
"Familiar-Possessed - Eria": fam("Eria the Water Charmer", 'AGUA'),
"Eria the Water Channeler": chan("Eria the Water Channeler", 'AGUA', 'Puedes descartar esta carta y otro monstruo de AGUA; añade a tu mano desde tu Deck 1 monstruo de AGUA con un Nivel igual o mayor que el del otro monstruo descartado; además, durante el resto de este turno no puedes activar efectos de monstruos que no sean de AGUA.'),
"Aussa the Earth Channeler": chan("Aussa the Earth Channeler", 'TIERRA', 'Puedes descartar esta carta y 1 monstruo de TIERRA; añade a tu mano desde tu Deck 1 monstruo de TIERRA con 1850 o menos ATK, cuyo Tipo original sea el mismo que el de uno de los monstruos descartados; además, durante el resto de este turno no puedes activar efectos de monstruos que no sean de TIERRA.'),
"Hiita the Fire Channeler": chan("Hiita the Fire Channeler", 'FUEGO', 'Puedes descartar esta carta y otro monstruo de FUEGO; añade a tu mano desde tu Deck 1 monstruo de FUEGO con más ATK que el otro monstruo descartado; además, durante el resto de este turno no puedes activar efectos de monstruos que no sean de FUEGO.'),
"Wynn the Wind Channeler": '(Esta carta se trata siempre como una carta ' + CH + '.)\nPuedes descartar esta carta y otro monstruo de VIENTO; añade a tu mano 1 monstruo de VIENTO con 1500 o menos DEF de tu Deck, excepto "Wynn the Wind Channeler"; además, durante el resto de este turno no puedes activar efectos de monstruos, excepto de monstruos de VIENTO. Cuando un monstruo de VIENTO que controles sea destruido en batalla mientras esta carta está en tu mano: puedes Invocar esta carta de Modo Especial.' + each("Wynn the Wind Channeler"),
"Unpossessed": 'Los monstruos ' + CH + ' que controlas no pueden ser destruidos en batalla. Si un monstruo ' + FP + ' que controles ataca a un monstruo del adversario, gana 800 ATK sólo durante el cálculo de daño. Si uno o más monstruos que controlas son destruidos en batalla o por un efecto de carta, mientras esta carta ya está boca arriba en tu Zona de Magia y Trampa: puedes Invocar de Modo Especial desde tu Deck, en Posición de Ataque o en Posición de Defensa boca abajo, 1 ' + SC1500 + ' cuyo Atributo sea diferente del Atributo original en el Campo de al menos 1 de esos monstruos destruidos.' + once("Unpossessed"),
"Possessed Destiny": 'Selecciona 1 monstruo boca arriba en el Campo; Invoca de Modo Especial desde tu mano, Deck o Cementerio, en Posición de Ataque boca arriba o en Posición de Defensa boca abajo, 1 monstruo ' + CH + ' o ' + FP + ' con el mismo Atributo y, después, puedes cambiar ese objetivo a Posición de Defensa boca abajo. Puedes desterrar esta carta de tu Cementerio y, después, seleccionar 1 monstruo que controles; cambia su posición de batalla.' + each("Possessed Destiny"),
"Spiritual Art Familiars": '(Esta carta se trata siempre como una carta ' + FP + '.)\nSi esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano desde tu Deck 1 Mágica/Trampa "Possessed" o 1 "Grand Spiritual Art - Ichirin". Puedes declarar 1 Tipo de Monstruo y 1 Atributo; esta carta pasa a ser de ese Tipo y Atributo hasta el final de este turno. Si esta carta es destruida en batalla o por un efecto de carta: puedes Invocar de Modo Especial 1 ' + SC1500 + ' de tu Deck o Cementerio.' + each("Spiritual Art Familiars"),
"Charmers of the Grand Circle": '2 o más monstruos ' + CH + ' o ' + FP + '\nSi esta carta es Invocada por Fusión: puedes activar este efecto; por cada Atributo original diferente usado para su Invocación por Fusión (máx. 4), puedes aplicar 1 efecto de esta lista. Puedes elegir el mismo efecto más de una vez. Resuelve cada efecto antes de volver a elegir.\n● Esta carta gana 800 ATK.\n● Añade a tu mano 1 Mágica/Trampa "Possessed" de tu Deck.\n● Devuelve a la mano 1 carta en el Campo.\n● Invoca de Modo Especial 1 monstruo de Tipo Lanzador de Conjuros de tu Cementerio.\n' + once("Charmers of the Grand Circle").strip(),
"Possessed Destiny - Wynn": '1 monstruo de Tipo Lanzador de Conjuros + 1 monstruo de VIENTO\n(Esta carta se trata siempre como una carta ' + FP + '.)\nSi esta carta es Invocada por Fusión: puedes colocar en la parte inferior del Deck 1 monstruo de VIENTO de tu Cementerio y, después, seleccionar 1 monstruo que controle tu adversario; toma el control de ese monstruo. Durante el turno de tu adversario (Efecto Rápido): puedes seleccionar 2 cartas en el Campo, incluyendo un monstruo de VIENTO que controles; colócalas en la parte inferior del Deck en cualquier orden. Sólo puedes usar 1 efecto de "Possessed Destiny - Wynn" por turno, y sólo una vez ese turno.',
"Awakening of the Possessed": 'Los monstruos que controlas ganan 300 ATK por cada Atributo diferente que controles. Los monstruos ' + CH + ' y ' + FP + ' que controlas no pueden ser destruidos por efectos de cartas. Si uno o más monstruos de Tipo Lanzador de Conjuros con 1850 de ATK original son Invocados de Modo Normal o Especial en tu Campo: roba 1 carta.' + once("Awakening of the Possessed"),
"Spirit Charmers": 'Descarta 1 carta; toma de tu Deck 2 cartas con nombres diferentes entre sí, que sean monstruos ' + CH + ', monstruos ' + FP + ' y/o Mágicas/Trampas "Possessed", añade 1 de ellas a tu mano y Coloca la otra.' + act1("Spirit Charmers"),
"Grand Spiritual Art - Ichirin": 'Niega el primer efecto de monstruo de tu adversario que se resuelva cada turno mientras controles un ' + SC1500 + '. Durante tu Main Phase: puedes revelar 1 monstruo de Tipo Lanzador de Conjuros de tu mano y, si lo haces, añade a tu mano desde tu Deck 1 monstruo con el mismo Atributo, pero con 1500 de ATK y 200 de DEF y, si haces eso, baraja la carta revelada en el Deck.' + once("Grand Spiritual Art - Ichirin"),
}
